def cache_sim(capacity, ttl, ops):
    cache = {}  # {key: (value, write_time)}
    lru_order = []  # list of keys in order of recency (most recent at end)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries for this key if it exists
            if key in cache:
                _, write_time = cache[key]
                if t >= write_time + ttl:
                    # Entry is expired, treat as absent
                    del cache[key]
                    lru_order.remove(key)

            # If key is absent and cache is full, evict LRU entry
            if key not in cache and len(cache) == capacity:
                lru_key = lru_order.pop(0)
                del cache[lru_key]

            # Add/update the entry
            cache[key] = (value, t)
            if key in lru_order:
                lru_order.remove(key)
            lru_order.append(key)

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache:
                value, write_time = cache[key]
                if t < write_time + ttl:
                    # Entry is valid
                    results.append(value)
                    # Mark as most recently used
                    lru_order.remove(key)
                    lru_order.append(key)
                else:
                    # Entry is expired
                    results.append(-1)
                    del cache[key]
                    lru_order.remove(key)
            else:
                results.append(-1)

    return results

